 haar leven onder ogen te zien.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1571744/schemerleven.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T14:24:00Z","review_batch":"nl006-reviewed-batch-07-20261101","evidence":[{"url":"https://metadata.isbn.nl/1571744/schemerleven.html","sha256":"7bd0ce3158d17c5eb597ea7386aa6cf8b2e566c30648207f85b6717b0c7364e9","checkedAt":"2026-11-01T14:09:24.660Z","fact":"Paperback ISBN 9789044549874 verschijningsdatum 07/10/2025 NUR 301 Literaire roman, novelle imprint De Geus uitgever Singel Uitgeverijen taal Nederlands","sourceAuthors":"Jaap Robben","identityNote":"Same canonical Work, translation attached to existing identity; no author/Work merge."}]}},{"relation":"works","ref":"work:new-jij-mag","key":{"id":977100102},"before":null,"after":{"native_identity_key":"nl-reviewed-isbn:9789044649192","title":"Jij mag alles zijn","author_id":930300048,"open_library_id":null,"source_type":"lumiscore_native","work_type":null,"first_publish_year":2021,"cover_id":null,"id":977100102}},{"relation":"editions","ref":"edition:9789044649192","key":{"id":977200146},"before":null,"after":{"work_id":977100102,"title":"Jij mag alles zijn","language":"nld","isbn_13":"9789044649192","isbn_10":null,"open_library_edition_id":null,"publisher":"Prometheus, Uitgeverij","id":977200146}},{"relation":"catalog_edition_metadata","ref":"metadata:9789044649192","key":{"edition_id":"@edition:9789044649192"},"before":null,"after":{"edition_id":"@edition:9789044649192","work_id":977100102,"bound_author_id":930300048,"bound_title":"Jij mag alles zijn","bound_language":"nld","bound_isbn13":"9789044649192","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000693979_Jij_mag_alles_zijn_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1457232/jij-mag-alles-zijn.html","review_s